local socket=require("socket")local json=require("braincloud.lib.json")local crypto=require("lib.crypto")local M={}local LOGIN_TIMEOUT=10*60 local MAX_BODY=64*1024 local SECURITY_HEADERS={["Cache-Control"]="no-store",["X-Content-Type-Options"]="nosniff",["Referrer-Policy"]="no-referrer",["Content-Security-Policy"]="default-src 'self'; img-src 'self'; style-src 'self' 'unsafe-inline'; ".."script-src 'self' 'unsafe-inline'; connect-src 'self'; frame-ancestors 'none'; form-action 'none'",}local STATUS_TEXT={[200]="OK",[302]="Found",[403]="Forbidden",[404]="Not Found",[405]="Method Not Allowed",[500]="Internal Server Error"}local function listen(port)local v4=socket.tcp()v4:setoption("reuseaddr",true)local ok,err=v4:bind("127.0.0.1",port)if not ok then v4:close()return nil,err end v4:listen(16)v4:settimeout(0)local _,actual=v4:getsockname()actual=tonumber(actual)local listeners={v4}if socket.tcp6 then local v6=socket.tcp6()v6:setoption("reuseaddr",true)pcall(function()v6:setoption("ipv6-v6only",true)end)if v6:bind("::1",actual)then v6:listen(16)v6:settimeout(0)listeners[#listeners+1]=v6 else v6:close()end end return listeners,actual end local function closeAll(listeners)for _,l in ipairs(listeners or{})do l:close()end end local function readRequest(conn)conn:settimeout(2)local line=conn:receive("*l")if not line then return nil end local method,target=line:match("^(%u+)%s+(%S+)")if not method then return nil end local headers={}while true do local h=conn:receive("*l")if not h or h==""then break end local k,v=h:match("^([^:]+):%s*(.*)$")if k then headers[k:lower()]=v end end local body=""local len=tonumber(headers["content-length"]or"0")or 0 if len>0 and len<=MAX_BODY then body=conn:receive(len)or""end local path,query=target:match("^([^?]*)%??(.*)$")return{method=method,path=path,query=query,headers=headers,body=body}end local function parseQuery(q)local out={}for pair in(q or""):gmatch("[^&]+")do local k,v=pair:match("^([^=]*)=?(.*)$")local function dec(s)return(s:gsub("+"," "):gsub("%%(%x%x)",function(h)return string.char(tonumber(h,16))end))end out[dec(k)]=dec(v)end return out end local function send(conn,status,ctype,body,extra)body=body or""local lines={"HTTP/1.1 "..status.." "..(STATUS_TEXT[status]or"OK"),"Content-Type: "..ctype,"Content-Length: "..#body,"Connection: close"}for k,v in pairs(SECURITY_HEADERS)do lines[#lines+1]=k..": "..v end for k,v in pairs(extra or{})do lines[#lines+1]=k..": "..v end conn:settimeout(5)conn:send(table.concat(lines,"\r\n").."\r\n\r\n"..body)conn:close()end local function hostAllowed(req,port)local host=(req.headers.host or""):lower()return host=="localhost:"..port or host=="127.0.0.1:"..port or host=="[::1]:"..port end local function originAllowed(req,port)local origin=req.headers.origin if not origin then return true end origin=origin:lower()return origin=="http://localhost:"..port or origin=="http://127.0.0.1:"..port or origin=="http://[::1]:"..port end local Server={}Server.__index=Server function M.new(session,opts)local self=setmetatable({},Server)self.session=session self.readAsset=opts.readAsset self.token=crypto.b64url(crypto.randomBytes(24))self.panel=nil self.callback=nil self.done=false return self end function Server:url()return"http://localhost:"..self.panelPort.."/"end function Server:start(port)local listeners,actual=listen(port or 0)if not listeners then error("could not open the setup panel port: "..tostring(actual))end self.panel,self.panelPort=listeners,actual end function Server:stop()self:_stopCallback()closeAll(self.panel)self.panel=nil end function Server:_stopCallback()closeAll(self.callback)self.callback=nil self.callbackDeadline=nil end function Server:beginLogin(serverUrl)self:_stopCallback()local listeners=listen(self.session.callbackPort)if not listeners then error({message="Another brainCloud login is in progress (port "..self.session.callbackPort.." is busy). Finish or cancel it, then try again."},0)end self.callback=listeners self.callbackDeadline=socket.gettime()+LOGIN_TIMEOUT return self.session:beginLogin(serverUrl)end function Server:cancelLogin()self:_stopCallback()self.session:cancelLogin()end local function acceptFrom(listeners)for _,l in ipairs(listeners or{})do local conn=l:accept()if conn then return conn end end return nil end function Server:poll()if self.callbackDeadline and socket.gettime()>self.callbackDeadline then self:_stopCallback()self.session:cancelLogin()end local conn=acceptFrom(self.callback)if conn then self:_handleCallback(conn)end for _=1,8 do conn=acceptFrom(self.panel)if not conn then break end self:_handlePanel(conn)end return self.done end function Server:_handleCallback(conn)local req=readRequest(conn)if not req or not hostAllowed(req,self.session.callbackPort)or req.method~="GET"or req.path~="/oauth/callback"then if req then send(conn,404,"text/plain","Not found")else conn:close()end return end local q=parseQuery(req.query)self.session:completeLogin(q.code,q.state,q.error)send(conn,302,"text/plain","",{Location=self:url()})self:_stopCallback()end local ROUTES={state=function(s)s:reloadIfIdle()end,cancel=function(s,_,server)server:cancelLogin()end,logout=function(s)s:logout()end,teams=function(s)s:refreshTeams()end,team=function(s,body)s:selectTeam(body.teamId)end,apps=function(s)s:refreshApps()end,app=function(s,body)s:selectApp(body.appId)end,create=function(s,body)local platforms={}for _,p in ipairs(type(body.platforms)=="table"and body.platforms or{})do platforms[#platforms+1]=tostring(p)end s:createApp(body.appName,platforms,body.templateAppId and tostring(body.templateAppId)or"")end,templates=function(s)s:refreshTemplates()end,save=function(s,body)s:saveSettings(body.serverUrl,body.appVersion,body.appId,body.appValue)end,done=function()end,}function Server:_handlePanel(conn)local req=readRequest(conn)if not req then conn:close()return end local ok,err=pcall(function()if not hostAllowed(req,self.panelPort)then return send(conn,403,"text/plain","Forbidden")end if req.method=="GET"then if req.path=="/"then local html=self.readAsset("index.html"):gsub("__SETUP_TOKEN__",self.token)return send(conn,200,"text/html; charset=utf-8",html)end if req.path=="/logo.png"or req.path=="/logo_light.png"then return send(conn,200,"image/png",self.readAsset(req.path:sub(2)))end return send(conn,404,"text/plain","Not found")end if req.method~="POST"or req.path:sub(1,5)~="/api/"then return send(conn,405,"text/plain","Method not allowed")end if not originAllowed(req,self.panelPort)or req.headers["x-setup-token"]~=self.token then return send(conn,403,"text/plain","Forbidden")end local okBody,body=pcall(json.decode,req.body~=""and req.body or"{}")if not okBody or type(body)~="table"then body={}end local action=req.path:sub(6)local extra={}if action=="login"then local okLogin,res=pcall(self.beginLogin,self,body.serverUrl)if okLogin then extra.authorizeUrl=res else self.session:reportError(type(res)=="table"and res.message or tostring(res))end else local route=ROUTES[action]if not route then return send(conn,404,"text/plain","Not found")end route(self.session,body,self)end local state=self.session:toJson()for k,v in pairs(extra)do state[k]=v end send(conn,200,"application/json",json.encode(state))if action=="done"then self.done=true end end)if not ok then print("setup error: "..tostring(err))pcall(send,conn,500,"text/plain","Setup error")end end return M
